#include <stdio.h>
#include <string.h>

#define MOD 1000000007

int main() {
    char s[200001];
    scanf("%s", s);
    int n = strlen(s);

    // Count a's and b's
    long long cnt_a = 0, cnt_b = 0;
    for (int i = 0; i < n; i++) {
        if (s[i] == 'a') cnt_a++;
        else cnt_b++;
    }

    // If only one type, only that string is reachable
    if (cnt_a == 0 || cnt_b == 0) {
        printf("1\n");
        return 0;
    }

    // Compute 2^(n-1) mod MOD
    long long pow2 = 1;
    for (int i = 0; i < n - 1; i++) {
        pow2 = (pow2 * 2) % MOD;
    }

    // Result is 2^(n-1)
    printf("%lld\n", pow2);

    return 0;
}

