#include <stdio.h>
#include <string.h>

#define MOD 1000000007LL

int main(void) {
    static char s[200005];
    if (scanf("%200000s", s) != 1) return 0;

    int n = (int)strlen(s);

    // Invariant:
    // Let a=0, b=1. Replacing "aa"->"b" changes length by -1 and
    // preserves sum of values modulo 2:
    //   0+0 == 1 (mod 2)? Not directly on symbol sum, but if we assign
    // weight F(c) where F(a)=1, F(b)=2, then:
    //   F(aa)=1+1=2 == F(b)
    //   F(bb)=2+2=4 == F(a) modulo 3
    // So total sum modulo 3 is invariant.
    //
    // Also, every string can be reduced until no equal adjacent pair remains,
    // hence to an alternating string. For each length L>=1, there are exactly
    // two alternating strings, and their modulo-3 sums differ. Thus for each
    // feasible length there is exactly one reachable alternating normal form.
    //
    // The reachable strings are exactly all strings having the same invariant
    // modulo 3 and length parity/size compatible with reductions from the
    // normal form. This yields a simple count:
    // if reduced alternating form has length m, then every length
    // m, m+1, ..., n with same value modulo ??? Actually each inverse operation
    // increases length by 1, and from the unique reduced form every such step
    // can generate some string. Therefore answer is n-m+1.
    //
    // We only need the length m of the fully reduced alternating form.
    // Simulate reduction with a stack: cancel equal adjacent pair into opposite char.
    // This is exactly the rewrite process and leads to the unique irreducible form.

    static char st[200005];
    int top = 0;

    for (int i = 0; i < n; i++) {
        st[top++] = s[i];
        while (top >= 2 && st[top - 1] == st[top - 2]) {
            char c = (st[top - 1] == 'a') ? 'b' : 'a';
            top -= 2;
            st[top++] = c;
        }
    }

    long long ans = n - top + 1;
    ans %= MOD;
    printf("%lld\n", ans);
    return 0;
}

import java.util.Scanner;

public class Main {
    static final int MOD = 1_000_000_007;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.nextLine().trim();
        int n = s.length();

        int target = 0;
        for (char c : s.toCharArray()) {
            if (c == 'a') target = (target + 1) % 3;
            else target = (target + 2) % 3;
        }

        // dp[r] = count of strings of current length with sum ≡ r mod 3
        long[] dp = new long[3];
        dp[1] = 1; // 'a'
        dp[2] = 1; // 'b'

        long ans = dp[target]; // length 1

        for (int len = 2; len <= n; len++) {
            long[] ndp = new long[3];
            ndp[0] = (dp[2] + dp[1]) % MOD; // (r-1) and (r-2) mod 3
            ndp[1] = (dp[0] + dp[2]) % MOD;
            ndp[2] = (dp[1] + dp[0]) % MOD;
            dp = ndp;
            ans = (ans + dp[target]) % MOD;
        }

        System.out.println(ans);
    }
}

