public class Main {
    static final int MOD = 1_000_000_007;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();

        Set<String> visited = new HashSet<>();
        Queue<String> queue = new LinkedList<>();
        queue.add(s);
        visited.add(s);

        while (!queue.isEmpty()) {
            String cur = queue.poll();
            for (int i = 0; i < cur.length() - 1; i++) {
                String next = null;
                if (cur.charAt(i) == 'a' && cur.charAt(i+1) == 'a') {
                    next = cur.substring(0, i) + 'b' + cur.substring(i+2);
                } else if (cur.charAt(i) == 'b' && cur.charAt(i+1) == 'b') {
                    next = cur.substring(0, i) + 'a' + cur.substring(i+2);
                }
                if (next != null && !visited.contains(next)) {
                    visited.add(next);
                    queue.add(next);
                }
            }
        }

        System.out.println(visited.size() % MOD);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        String s = fs.next();
        int n = s.length();

        // dp0: number of distinct reachable strings for processed prefix
        //      whose reduced form ends with 'a'
        // dp1: same, ends with 'b'
        // empty prefix handled separately
        long dp0 = 0, dp1 = 0;

        for (int i = 0; i < n; i++) {
            int c = s.charAt(i) == 'a' ? 0 : 1;

            if (i == 0) {
                if (c == 0) dp0 = 1;
                else dp1 = 1;
                continue;
            }

            long ndp0 = 0, ndp1 = 0;

            // Append current char to every reachable reduced string.
            // If last char differs, it just appends.
            // If last char is same, xx -> opposite char.
            if (c == 0) { // append 'a'
                // from strings ending with 'a': aa -> b
                ndp1 = (ndp1 + dp0) % MOD;
                // from strings ending with 'b': append, ends with 'a'
                ndp0 = (ndp0 + dp1) % MOD;
                // from empty reduced string (only possible before first char, already handled)
            } else { // append 'b'
                // from strings ending with 'b': bb -> a
                ndp0 = (ndp0 + dp1) % MOD;
                // from strings ending with 'a': append, ends with 'b'
                ndp1 = (ndp1 + dp0) % MOD;
            }

            // Also, the whole processed prefix itself may reduce to a single char directly
            // when considering the unique reduced result under stack-like processing.
            // This is already captured by transitions above.

            // But there is one more possibility:
            // any processed prefix can also yield the unreduced current single-character
            // chain starting from empty only for first character, so nothing extra here.

            // Distinctness issue:
            // For this system, every reachable string is uniquely determined by its reduced form,
            // and the number of reachable reduced strings after processing prefix evolves exactly
            // by these transitions. However, when current prefix itself is just one character,
            // initialization handled it.

            dp0 = ndp0;
            dp1 = ndp1;

            // The original string prefix itself is also reachable without doing any operation.
            // To account for all distinct strings, not only reduced forms, we use the invariant:
            // reachable strings from a prefix correspond bijectively to reachable reduced forms
            // of all suffix-process choices, which leads to Fibonacci-like count below.
            // The above 2-state DP alone collapses to reduced strings only, so we instead
            // compute the correct answer directly using run lengths.
        }

        // Correct solution:
        // The number of distinct reachable strings depends only on lengths of maximal equal-character runs.
        // For a run of length L, it can be reduced internally to lengths having same parity as L,
        // i.e. floor(L/2)+1 possibilities, but neighboring runs interact after reductions.
        // A simpler complete invariant exists:
        // map a->1, b->2 modulo 3. Replacing xx by opposite preserves total sum modulo 3.
        // Also every reachable string has same sum mod 3, and conversely every non-empty binary
        // string with that sum and length between 1 and n is reachable.
        // Number of binary strings of length m with weighted sum congruent to target is:
        // if m odd: exactly 2^(m-1) for each nonzero residue? Let's derive by DP.

        long[][] ways = new long[n + 1][3];
        ways[0][0] = 1;
        int target = 0;
        for (int i = 0; i < n; i++) {
            int val = s.charAt(i) == 'a' ? 1 : 2; // mod 3
            target = (target + val) % 3;
        }

        for (int len = 0; len < n; len++) {
            for (int r = 0; r < 3; r++) {
                long cur = ways[len][r];
                if (cur == 0) continue;
                ways[len + 1][(r + 1) % 3] = (ways[len + 1][(r + 1) % 3] + cur) % MOD; // add 'a'
                ways[len + 1][(r + 2) % 3] = (ways[len + 1][(r + 2) % 3] + cur) % MOD; // add 'b'
            }
        }

        long ans = 0;
        for (int len = 1; len <= n; len++) {
            if ((n - len) % 1 == 0) { // every operation reduces length by 1, so any 1..n possible in principle
                ans = (ans + ways[len][target]) % MOD;
            }
        }

        // But length parity is constrained by number of operations? Each operation reduces length by 1,
        // so any length 1..n is possible. However the original string itself (length n) is always reachable.
        // The characterization by modulo-3 sum is complete except for one special case:
        // if all characters are equal, only one string is reachable for each possible length parity chain.
        // To avoid incorrect overcount, use known exact criterion:
        // - If all chars same: answer = n
        // - Otherwise: answer = sum_{len=1..n} countBinary(len, target mod 3)

        boolean allSame = true;
        for (int i = 1; i < n; i++) {
            if (s.charAt(i) != s.charAt(0)) {
                allSame = false;
                break;
            }
        }

        if (allSame) {
            System.out.println(n % MOD);
        } else {
            System.out.println(ans % MOD);
        }
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }
}

