        vector<long long> ndp(3,0);
        if(k==1){ ndp[1]=1; ndp[2]=1; }
        else { for(int x=0;x<3;x++){ ndp[(x+1)%3]=(ndp[(x+1)%3]+dp[x])%MOD; ndp[(x+2)%3]=(ndp[(x+2)%3]+dp[x])%MOD; } }
        dp = ndp;
        ans = (ans + dp[r]) % MOD;
    }
