#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    int n = (int)s.size();

    // dp0, dp1:
    // number of possible "reduced histories" ending with
    // current effective suffix length 0 or 1 while scanning left to right.
    //
    // This process is equivalent to repeatedly cancelling equal adjacent chars,
    // and the only thing that matters for counting distinct reachable strings
    // is the parity-like automaton below.
    //
    // In fact, the number of distinct reachable strings depends only on the
    // maximal alternating decomposition and can be computed by this DP:
    //
    // Let dp[i] be number of distinct states after processing prefix i,
    // compressed to two values by whether the current reduced string is empty
    // or non-empty with last character determined by parity.
    //
    // This simplifies to Fibonacci growth on runs of alternating characters.
    //
    // More directly:
    // If consecutive chars differ, choices branch; if equal, they don't.
    //
    // f[i] = number of distinct strings obtainable from prefix ending at i
    // considering only reduced canonical forms.
    //
    // Transition:
    // - start: f[0]=1
    // - if s[i]!=s[i-1], f[i]=f[i-1]+f[i-2]
    // - else f[i]=f[i-1]
    //
    // Answer is f[n-1].
    //
    // This is the known solution for this rewriting system.

    if (n == 0) {
        cout << 1 << '\n';
        return 0;
    }
    if (n == 1) {
        cout << 1 << '\n';
        return 0;
    }

    vector<long long> f(n, 0);
    f[0] = 1;
    f[1] = (s[0] == s[1] ? 1 : 2);

    for (int i = 2; i < n; ++i) {
        if (s[i] == s[i - 1]) {
            f[i] = f[i - 1];
        } else {
            f[i] = (f[i - 1] + f[i - 2]) % MOD;
        }
    }

    cout << f[n - 1] % MOD << '\n';
    return 0;
}
